INSERT INTO content_packages (id, code, title, package_type, topic_id, status) VALUES ('33000000-0000-4000-8000-010000000001', 'PS-R65-INF-2', 'Luyện thêm: Xe buýt đêm - suy luận có căn cứ', 'PRACTICE_SET', NULL, 'PUBLISHED');
INSERT INTO content_package_versions (id, package_id, version_number, status, rules, schema_version, published_at) VALUES ('33000000-0000-4000-8000-020000000001', '33000000-0000-4000-8000-010000000001', 1, 'PUBLISHED', '{}'::jsonb, 1, CURRENT_TIMESTAMP);
INSERT INTO content_sections (id, package_version_id, title, skill, sort_order) VALUES ('33000000-0000-4000-8000-030000000001', '33000000-0000-4000-8000-020000000001', 'The night bus trial', 'READING', 1);
INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('33000000-0000-4000-8000-040000000001', 'PASSAGE', 'A fictional coastal town trialled a late-night bus on Fridays and Saturdays. Before the trial, the council expected students to be the main users. After eight weeks, ticket checks showed that nearly half of the passengers were hospital and restaurant staff finishing their shifts. Use was highest between 11 p.m. and midnight, then dropped sharply. A council officer noted that complaints about taxi prices fell during the same period, although the council had not changed taxi fares. Business owners reported that staff were less often late for early shifts. The council has extended the trial for three months and will publish passenger surveys before deciding whether to make the service permanent.', 'VALID');
INSERT INTO content_asset_links (id, asset_id, section_id, sort_order) VALUES ('33000000-0000-4000-8000-050000000001', '33000000-0000-4000-8000-040000000001', '33000000-0000-4000-8000-030000000001', 0);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-060000000001', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000001', '33000000-0000-4000-8000-060000000001', 1, 'Which conclusion is best supported by the passage?', '[{"optionKey": "A", "content": "Students were the main users of the night bus.", "sortOrder": 1}, {"optionKey": "B", "content": "The night bus helped workers get home after late shifts.", "sortOrder": 2}, {"optionKey": "C", "content": "The night bus caused taxi prices to fall.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "B"}'::jsonb, 1, 'Gần một nửa hành khách là nhân viên bệnh viện và nhà hàng vừa tan ca. A trái với số liệu; C là bẫy nhân quả: bài chỉ nói số lời phàn nàn giảm, không nói giá taxi giảm.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000001', (SELECT id FROM knowledge_points WHERE code = 'R65_EVIDENCE_INFERENCE'), 1.00);
INSERT INTO section_questions (id, section_id, question_version_id, sort_order, max_score) VALUES ('33000000-0000-4000-8000-080000000001', '33000000-0000-4000-8000-030000000001', '33000000-0000-4000-8000-070000000001', 1, 1.00);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-060000000002', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000002', '33000000-0000-4000-8000-060000000002', 1, 'What can be inferred from the sentence about complaints concerning taxi prices?', '[{"optionKey": "A", "content": "Some residents may have used the bus instead of paying for taxis.", "sortOrder": 1}, {"optionKey": "B", "content": "Taxi drivers lowered their fares.", "sortOrder": 2}, {"optionKey": "C", "content": "The council plans to ban taxis at night.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "A"}'::jsonb, 1, 'Giá taxi không đổi nhưng phàn nàn giảm, nên suy luận hợp lý là một số người đi xe buýt thay taxi. B trái với bài (giá không đổi); C không có căn cứ.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000002', (SELECT id FROM knowledge_points WHERE code = 'R65_EVIDENCE_INFERENCE'), 1.00);
