INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000003', '33000000-0000-4000-8000-060000000003', 1, 'The council will publish passenger ______ before deciding whether to make the service permanent.', NULL, '{"type": "FILL", "accepted": ["surveys", "survey"]}'::jsonb, 1, 'Câu cuối: "publish passenger surveys before deciding".', 'MEDIUM', 'PUBLISHED');
