INSERT INTO content_package_versions (id, package_id, version_number, status, rules, schema_version, published_at) VALUES ('33000000-0000-4000-8000-020000000002', '33000000-0000-4000-8000-010000000002', 1, 'PUBLISHED', '{}'::jsonb, 1, CURRENT_TIMESTAMP);
INSERT INTO content_sections (id, package_version_id, title, skill, sort_order) VALUES ('33000000-0000-4000-8000-030000000002', '33000000-0000-4000-8000-020000000002', 'Sunday opening at the library', 'READING', 1);
INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('33000000-0000-4000-8000-040000000002', 'PASSAGE', 'A fictional town library began opening on Sundays last January. Over the following six months, total book loans rose by 18 per cent, while weekday loans stayed almost the same. A visitor count showed that families with young children made up most Sunday visits, and the children''s section was often full by noon. Staffing costs increased, and the library board admitted that it had not yet found extra funding. In a short survey, six out of ten Sunday visitors said they would use the library less often if it returned to weekday-only hours. The board will review the figures in December.', 'VALID');
INSERT INTO content_asset_links (id, asset_id, section_id, sort_order) VALUES ('33000000-0000-4000-8000-050000000002', '33000000-0000-4000-8000-040000000002', '33000000-0000-4000-8000-030000000002', 0);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-060000000004', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000004', '33000000-0000-4000-8000-060000000004', 1, 'Which statement is best supported by the passage?', '[{"optionKey": "A", "content": "Sunday opening mainly benefited families with young children.", "sortOrder": 1}, {"optionKey": "B", "content": "Weekday loans fell because of Sunday opening.", "sortOrder": 2}, {"optionKey": "C", "content": "The library has secured funding for its Sunday staff.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "A"}'::jsonb, 1, 'Gia đình có trẻ nhỏ chiếm phần lớn lượt khách Chủ nhật và khu thiếu nhi thường đầy. B trái với bài (lượt mượn ngày thường gần như không đổi); C trái với bài (chưa tìm được nguồn tài trợ).', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000004', (SELECT id FROM knowledge_points WHERE code = 'R65_EVIDENCE_INFERENCE'), 1.00);
INSERT INTO section_questions (id, section_id, question_version_id, sort_order, max_score) VALUES ('33000000-0000-4000-8000-080000000004', '33000000-0000-4000-8000-030000000002', '33000000-0000-4000-8000-070000000004', 1, 1.00);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-060000000005', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000005', '33000000-0000-4000-8000-060000000005', 1, 'What can be inferred from the survey result?', '[{"optionKey": "A", "content": "Every visitor wants Sunday opening to continue for ever.", "sortOrder": 1}, {"optionKey": "B", "content": "Sunday hours may be encouraging some people to visit more often.", "sortOrder": 2}, {"optionKey": "C", "content": "Most visitors dislike the weekday opening hours.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "B"}'::jsonb, 1, '6/10 người nói sẽ đến ít hơn nếu bỏ giờ Chủ nhật, nên giờ Chủ nhật có thể khiến một số người đến thường xuyên hơn. A khái quát quá mức ("every"); C không có căn cứ.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000005', (SELECT id FROM knowledge_points WHERE code = 'R65_EVIDENCE_INFERENCE'), 1.00);
