INSERT INTO content_package_versions (id, package_id, version_number, status, rules, schema_version, published_at) VALUES ('33000000-0000-4000-8000-020000000003', '33000000-0000-4000-8000-010000000003', 1, 'PUBLISHED', '{}'::jsonb, 1, CURRENT_TIMESTAMP);
INSERT INTO content_sections (id, package_version_id, title, skill, sort_order) VALUES ('33000000-0000-4000-8000-030000000003', '33000000-0000-4000-8000-020000000003', 'The community orchestra', 'READING', 1);
INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('33000000-0000-4000-8000-040000000003', 'PASSAGE', 'A fictional community orchestra was founded twelve years ago by a retired music teacher. At first it had only fourteen members, most of them beginners, and rehearsals took place in a church hall. Membership has since tripled, partly because the orchestra now offers free lessons to anyone under sixteen. Concerts are held four times a year, and tickets are priced to cover costs rather than to make a profit. Last year, a local company agreed to pay for new instruments, which means the orchestra can now lend equipment to young players who cannot afford their own.', 'VALID');
INSERT INTO content_asset_links (id, asset_id, section_id, sort_order) VALUES ('33000000-0000-4000-8000-050000000003', '33000000-0000-4000-8000-040000000003', '33000000-0000-4000-8000-030000000003', 0);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-060000000007', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000007', '33000000-0000-4000-8000-060000000007', 1, 'Which option is closest in meaning to "Membership has since tripled"?', '[{"optionKey": "A", "content": "The orchestra now has three times as many members as it had at the start.", "sortOrder": 1}, {"optionKey": "B", "content": "The orchestra has gained three new members.", "sortOrder": 2}, {"optionKey": "C", "content": "Membership fees have risen threefold.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "A"}'::jsonb, 1, '"Tripled" nghĩa là gấp ba (14 thành 42 người). B sai số lượng; C đổi chủ đề sang phí thành viên.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000007', (SELECT id FROM knowledge_points WHERE code = 'R65_PARAPHRASE'), 1.00);
INSERT INTO section_questions (id, section_id, question_version_id, sort_order, max_score) VALUES ('33000000-0000-4000-8000-080000000007', '33000000-0000-4000-8000-030000000003', '33000000-0000-4000-8000-070000000007', 1, 1.00);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-060000000008', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000008', '33000000-0000-4000-8000-060000000008', 1, 'Which option is closest in meaning to "tickets are priced to cover costs rather than to make a profit"?', '[{"optionKey": "A", "content": "Tickets are so cheap that the orchestra loses money.", "sortOrder": 1}, {"optionKey": "B", "content": "The orchestra charges only what it needs to pay its expenses.", "sortOrder": 2}, {"optionKey": "C", "content": "The orchestra refuses to sell tickets.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "B"}'::jsonb, 1, '"Cover costs" là đủ bù chi phí, "rather than profit" là không tính lợi nhuận. A suy diễn lỗ vốn; C không có trong bài.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000008', (SELECT id FROM knowledge_points WHERE code = 'R65_PARAPHRASE'), 1.00);
