INSERT INTO content_package_versions (id, package_id, version_number, status, rules, schema_version, published_at) VALUES ('33000000-0000-4000-8000-020000000004', '33000000-0000-4000-8000-010000000004', 1, 'PUBLISHED', '{}'::jsonb, 1, CURRENT_TIMESTAMP);
INSERT INTO content_sections (id, package_version_id, title, skill, sort_order) VALUES ('33000000-0000-4000-8000-030000000004', '33000000-0000-4000-8000-020000000004', 'The harbour beach clean-up', 'READING', 1);
INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('33000000-0000-4000-8000-040000000004', 'PASSAGE', 'A fictional charity organises a monthly clean-up of a harbour beach. Volunteers collect rubbish, sort it and record what they find. Plastic bottles used to be the most common item, but since a deposit scheme began, they account for far fewer items than cigarette ends. The charity has also noticed that the amount of rubbish rises sharply after public holidays. Because of this, it now asks local cafes to provide bins with lids during busy weekends. The charity says the data helps it persuade the council to act, although it admits that cleaning the beach alone will not solve the problem.', 'VALID');
INSERT INTO content_asset_links (id, asset_id, section_id, sort_order) VALUES ('33000000-0000-4000-8000-050000000004', '33000000-0000-4000-8000-040000000004', '33000000-0000-4000-8000-030000000004', 0);
INSERT INTO questions (id, question_type, skill, status) VALUES ('33000000-0000-4000-8000-06000000000a', 'MULTIPLE_CHOICE', 'READING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-07000000000a', '33000000-0000-4000-8000-06000000000a', 1, 'Which option is closest in meaning to "they account for far fewer items than cigarette ends"?', '[{"optionKey": "A", "content": "Bottles now make up a much smaller share of the rubbish than cigarette ends.", "sortOrder": 1}, {"optionKey": "B", "content": "Cigarette ends have been banned from the beach.", "sortOrder": 2}, {"optionKey": "C", "content": "Fewer bottles are sold than cigarettes.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "A"}'::jsonb, 1, '"Account for far fewer items" là chiếm tỉ lệ nhỏ hơn nhiều. B và C đưa thông tin không có trong bài.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-07000000000a', (SELECT id FROM knowledge_points WHERE code = 'R65_PARAPHRASE'), 1.00);
