INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-07000000000b', '33000000-0000-4000-8000-06000000000b', 1, 'Which option is closest in meaning to "cleaning the beach alone will not solve the problem"?', '[{"optionKey": "A", "content": "Collecting rubbish is not enough without other action.", "sortOrder": 1}, {"optionKey": "B", "content": "The beach can never be cleaned.", "sortOrder": 2}, {"optionKey": "C", "content": "The charity has stopped cleaning the beach.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "A"}'::jsonb, 1, '"Alone" nghĩa là chỉ riêng việc dọn dẹp là chưa đủ. B cực đoan hóa; C trái với bài (vẫn dọn hằng tháng).', 'MEDIUM', 'PUBLISHED');
