INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-07000000000d', '33000000-0000-4000-8000-06000000000d', 1, 'Some people say that cities should ban cars from the centre to reduce pollution. To what extent do you agree or disagree? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', NULL, '{"task": "TASK_2", "type": "ESSAY", "minWords": 250, "passBand": 6}'::jsonb, 1, 'Bài được chấm theo bốn tiêu chí: Task Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy. Nêu rõ quan điểm ngay phần mở bài và giữ nhất quán đến hết bài.', 'EASY', 'PUBLISHED');
