INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000015', '33000000-0000-4000-8000-060000000015', 1, 'The bar chart below shows the percentage of households with internet access in three countries in 2005 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.', NULL, '{"task": "TASK_1", "type": "ESSAY", "minWords": 150, "passBand": 6.0, "chartFacts": "Share of households with internet access (%). Country A: 2005 34, 2020 88. Country B: 2005 21, 2020 72. Country C: 2005 52, 2020 94. Increase: A 54 points, B 51 points, C 42 points. Key features: access rose in every country; Country C was highest in both years and Country B lowest in both years; the gap between highest and lowest narrowed from 31 points in 2005 to 22 points in 2020; Country A had the largest increase."}'::jsonb, 1, 'Bài được chấm theo bốn tiêu chí, trong đó Task Achievement cần có đoạn tổng quan (overview) nêu xu hướng chính và báo cáo số liệu chính xác, không liệt kê hết mọi số.', 'EASY', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000015', (SELECT id FROM knowledge_points WHERE code = 'DEMO_READING_W1_CHART'), 1.00);
