INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000016', '33000000-0000-4000-8000-060000000016', 1, 'The bar chart below shows the average number of hours per week that teenagers in two age groups spend on reading, sport and gaming. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.', NULL, '{"task": "TASK_1", "type": "ESSAY", "minWords": 150, "passBand": 6.0, "chartFacts": "Average hours per week. Reading: ages 13-15 3, ages 16-18 2. Sport: ages 13-15 5, ages 16-18 4. Gaming: ages 13-15 8, ages 16-18 11. Key features: gaming was the most time-consuming activity in both age groups and was the only one to rise with age (8 to 11 hours); reading and sport both fell by 1 hour; for ages 16-18, gaming (11 hours) exceeded reading and sport combined (6 hours)."}'::jsonb, 1, 'Bài được chấm theo bốn tiêu chí, trong đó Task Achievement cần có đoạn tổng quan (overview) nêu xu hướng chính và báo cáo số liệu chính xác, không liệt kê hết mọi số.', 'EASY', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('33000000-0000-4000-8000-070000000016', (SELECT id FROM knowledge_points WHERE code = 'DEMO_READING_W1_CHART'), 1.00);
