INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('33000000-0000-4000-8000-070000000017', '33000000-0000-4000-8000-060000000017', 1, 'The bar chart below shows the average number of daily visitors to three museums on weekdays and at weekends. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.', NULL, '{"task": "TASK_1", "type": "ESSAY", "minWords": 150, "passBand": 6.0, "chartFacts": "Average daily visitors. Maritime: weekdays 420, weekends 980. Science: weekdays 650, weekends 1,200. Art: weekdays 380, weekends 540. Increase at weekends: Maritime 560, Science 550, Art 160. Key features: every museum had more visitors at weekends; the Science museum was busiest and the Art museum quietest on both kinds of day; the Maritime museum''s visitors more than doubled at weekends (420 to 980) while the Art museum''s rose by only 160."}'::jsonb, 1, 'Bài được chấm theo bốn tiêu chí, trong đó Task Achievement cần có đoạn tổng quan (overview) nêu xu hướng chính và báo cáo số liệu chính xác, không liệt kê hết mọi số.', 'EASY', 'PUBLISHED');
